"""Generate CALIBRATION.md from the two independent calibration summaries (Hays County TX, Tehama County CA). usage: calibration_md.py
Inputs: tables/validation_hays_repair_summary.txt, tables/validation_hays_repair_metrics.csv, tables/validation_tehama_repair_summary.txt, tables/validation_tehama_repair.csv."""
import sys, time, pandas as pd
import os as _os; sys.path.insert(0, _os.path.dirname(_os.path.abspath(__file__)))
from common import *
H = open(f"{OUT}/validation_hays_repair_summary.txt").read().strip(); Tt = open(f"{OUT}/validation_tehama_repair_summary.txt").read().strip()
HM = pd.read_csv(f"{OUT}/validation_hays_repair_metrics.csv"); TR = pd.read_csv(f"{OUT}/validation_tehama_repair.csv")
b0 = TR[TR.radius_m == 0].set_index(["community", "neighborhood"]); rows = []
for rad in sorted(TR.radius_m.unique()):
    s = TR[TR.radius_m == rad].set_index(["community", "neighborhood"]); rows.append((rad, int((s.flag & b0.flag).sum()), int(b0.flag.sum())))
L = [f"# CALIBRATION.md - how far can the 'latent connection' repairs be trusted? (generated by egress/calibration_md.py)\n",
     "Idea: independent documentation says which neighbourhoods really have ONE way out (Tehama County CA: 32 documented single-ingress areas) and which have several (Hays County TX: 26 one-exit, 31 multi-exit neighbourhoods). If connecting dead-end tips to a nearby unconnected road mostly repairs genuine digitising gaps, agreement with the documentation should stay or improve; if it removes the flags of documented single-exit areas, the added connections are mostly not real.\n",
     "## Hays County (validation/validate_hays_repair.py)\n```\n" + H + "\n```\n",
     "## Tehama County (validation/validate_tehama_repair.py)\n```\n" + Tt + "\n```\n",
     "## Side by side: documented single-exit flags lost by the repair",
     "| repair radius | Hays: one-exit areas still flagged (of 26; 17 flagged at baseline) | Tehama: baseline flags retained (of 24) |\n|---|---|---|"]
for (rad, kept, base), (_, hm) in zip(rows, HM.iterrows()):
    L.append(f"| {'baseline' if rad == 0 else str(int(rad)) + ' m'} | {int(hm.true_positives)} | {kept} |")
L.append("\n## Reading\n"
         "* Neither label set IMPROVES with repair. At <= 25 m the effect is within +-1 flag (Hays 17 -> 17; Tehama 24 -> 23), so real digitising gaps cannot be separated from spurious touching (private drives, fences) by this check: treat the 3.9 % pooled <= 25 m flip as an UPPER BOUND on the map-induced share.\n"
         "* 50 m costs one documented flag in each set (Hays 17 -> 16, Tehama 24 -> 23): the <= 50 m candidates (8-19 % of S30) are a verification list, not a correction.\n"
         "* >= 100 m is not credible: Hays loses 6 of 17 documented single-exit flags at 100 m; Tehama loses 6 of 24 at 250 m and its dose-response (documented population vs graph load) collapses from Spearman 0.86 to 0.30.\n"
         "* Consistent conclusion: the single-link exposure is mostly REAL (documented areas stay flagged under moderate repair), and the map-induced part is small and unproven.\n"
         "* Limits: two counties, 84 neighbourhoods, flags are small integers (one flag = 4-6 %); Hays centroids are matched to the K nearest buildings, Tehama areas by road-name regex inside town boxes.\n")
open(f"{LANE}/CALIBRATION.md", "w").write("\n".join(L)); print("wrote CALIBRATION.md")
